/bin/zsh -lc "python3 -c 'from collections import Counter
for init in ([2],[3],[1,2],[1,1,1],[2,2,2],[1,2,1,2],[1,2,3,4],[2,3,2,3],[1,1,2,2,3,3], [10]*5, [2]*10):
 a=list(init); c=Counter(a)
 for n in range(2000):
  x=c[a[-1]]; a.append(x); c[x]+=1
 print(init,\"last\",a[-30:],\"parity sets\",*[sorted(set(a[-200+p::2])) for p in (0,1)])'"

